    private JPanel buildDashboard() {
        JPanel page = new JPanel(new BorderLayout(18, 18));
        page.setBorder(new EmptyBorder(28, 36, 28, 36));
        page.setBackground(new Color(245, 248, 252));

        JPanel header = new JPanel(new BorderLayout());
        header.setOpaque(false);
        JLabel title = new JLabel("QuizGame Generator");
        title.setFont(new Font("SansSerif", Font.BOLD, 30));
        JLabel subtitle = new JLabel("<html>Practice coding and computer science with randomized multiple-choice quizzes.</html>");
        subtitle.setFont(new Font("SansSerif", Font.PLAIN, 15));
        subtitle.setForeground(new Color(80, 90, 105));
        JPanel titleStack = new JPanel(new GridLayout(0, 1, 0, 7));
        titleStack.setOpaque(false);
        titleStack.add(title);
        titleStack.add(subtitle);
        header.add(titleStack, BorderLayout.CENTER);
        page.add(header, BorderLayout.NORTH);

        JPanel settings = new JPanel(new GridBagLayout());
        settings.setBackground(Color.WHITE);
        settings.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(220, 226, 235)),
                new EmptyBorder(22, 24, 22, 24)));
        GridBagConstraints c = new GridBagConstraints();
        c.insets = new Insets(10, 8, 10, 8);
        c.fill = GridBagConstraints.HORIZONTAL;
        c.gridx = 0; c.gridy = 0; c.weightx = 0.35;
        settings.add(label("Choose subject"), c);
        c.gridx = 1; c.weightx = 0.65;
        subjectBox.setFont(new Font("SansSerif", Font.PLAIN, 15));
        settings.add(subjectBox, c);
        c.gridx = 0; c.gridy++; c.weightx = 0.35;
        settings.add(label("Difficulty"), c);
        c.gridx = 1; c.weightx = 0.65;
        difficultyBox.setFont(new Font("SansSerif", Font.PLAIN, 15));
        settings.add(difficultyBox, c);
        c.gridx = 0; c.gridy++; c.weightx = 0.35;
        settings.add(label("Number of questions"), c);
        c.gridx = 1; c.weightx = 0.65;
        countBox.setFont(new Font("SansSerif", Font.PLAIN, 15));
        settings.add(countBox, c);

        JLabel info = new JLabel("<html><b>Question Bank:</b> " + localBank.size()
                + " questions across "
                + localBank.stream().map(q -> q.subject).distinct().count()
                + " technical subjects.<br>Choose your subject, difficulty, and quiz length.<br>Practice with randomized MCQs and explanations.</html>");
        info.setForeground(new Color(70, 82, 98));
        c.gridx = 0; c.gridy++; c.gridwidth = 2; c.weightx = 1;
        settings.add(info, c);

        JButton start = new JButton("Start quiz");
        start.setFont(new Font("SansSerif", Font.BOLD, 16));
        start.setBackground(new Color(37, 99, 235));
        start.setForeground(Color.WHITE);
        start.setOpaque(true);
        start.setContentAreaFilled(true);
        start.setBorderPainted(false);
        start.setFocusPainted(false);
        start.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        start.setPreferredSize(new Dimension(240, 48));
        start.setToolTipText("Start a quiz with your selected subject and difficulty");
        // Keep the click handler attached to the actual button.
        start.addActionListener(e -> startLocalQuiz());

        JPanel center = new JPanel(new BorderLayout(0, 18));
        center.setOpaque(false);
        center.add(settings, BorderLayout.CENTER);
        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.CENTER));
        buttons.setOpaque(false);
        buttons.add(start);
        center.add(buttons, BorderLayout.SOUTH);
        page.add(center, BorderLayout.CENTER);

        statusLabel.setFont(new Font("SansSerif", Font.PLAIN, 12));
        statusLabel.setForeground(new Color(75, 90, 105));
        page.add(statusLabel, BorderLayout.SOUTH);
        return page;
    }

    private JPanel buildQuizPanel() {
        JPanel page = new JPanel(new BorderLayout(18, 18));
        page.setBorder(new EmptyBorder(28, 36, 28, 36));
        page.setBackground(new Color(245, 248, 252));

        JPanel top = new JPanel(new BorderLayout());
        top.setOpaque(false);
        questionCounter.setFont(new Font("SansSerif", Font.BOLD, 14));
        JButton back = new JButton("Exit quiz");
        back.addActionListener(e -> {
            if (JOptionPane.showConfirmDialog(this,
                    "Exit this quiz and return to subjects?", "Exit quiz",
                    JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION) {
                cards.show(root, "dashboard");
            }
        });
        top.add(questionCounter, BorderLayout.WEST);
        top.add(back, BorderLayout.EAST);
        page.add(top, BorderLayout.NORTH);

        JPanel body = new JPanel(new BorderLayout(0, 18));
        body.setBackground(Color.WHITE);
        body.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(220, 226, 235)),
                new EmptyBorder(24, 26, 24, 26)));
        questionLabel.setFont(new Font("SansSerif", Font.BOLD, 20));
        questionLabel.setVerticalAlignment(SwingConstants.TOP);
        body.add(questionLabel, BorderLayout.NORTH);

        optionPanel.setBackground(Color.WHITE);
        optionPanel.setBorder(new EmptyBorder(8, 0, 8, 0));
        for (int i = 0; i < 4; i++) {
            optionButtons[i] = new JRadioButton();
            optionButtons[i].setFont(new Font("SansSerif", Font.PLAIN, 16));
            optionButtons[i].setBackground(Color.WHITE);
            optionButtons[i].setFocusPainted(false);
            optionGroup.add(optionButtons[i]);
            optionPanel.add(optionButtons[i]);
        }
        body.add(optionPanel, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout(10, 10));
        bottom.setOpaque(false);
        feedbackLabel.setFont(new Font("SansSerif", Font.PLAIN, 14));
        feedbackLabel.setVerticalAlignment(SwingConstants.TOP);
        sourceLabel.setFont(new Font("SansSerif", Font.ITALIC, 11));
        sourceLabel.setForeground(new Color(95, 105, 120));
        JPanel feedbackStack = new JPanel(new BorderLayout(0, 5));
        feedbackStack.setOpaque(false);
        feedbackStack.add(feedbackLabel, BorderLayout.CENTER);
        feedbackStack.add(sourceLabel, BorderLayout.SOUTH);
        bottom.add(feedbackStack, BorderLayout.CENTER);
        actionButton.setFont(new Font("SansSerif", Font.BOLD, 15));
        actionButton.setPreferredSize(new Dimension(180, 44));
        actionButton.addActionListener(e -> handleQuizAction());
        bottom.add(actionButton, BorderLayout.EAST);
        body.add(bottom, BorderLayout.SOUTH);
        page.add(body, BorderLayout.CENTER);
        return page;
    }

    private JLabel label(String text) {
        JLabel label = new JLabel(text);
        label.setFont(new Font("SansSerif", Font.BOLD, 15));
        return label;
    }

    private void startLocalQuiz() {
        String subject = (String) subjectBox.getSelectedItem();
        String difficulty = (String) difficultyBox.getSelectedItem();
        int count = (Integer) countBox.getSelectedItem();

        List<Question> candidates = localBank.stream()
                .filter(q -> q.subject.equals(subject))
                .filter(q -> difficulty.equals("Any difficulty") || q.difficulty.equals(difficulty))
                .collect(Collectors.toCollection(ArrayList::new));

        if (candidates.isEmpty()) {
            JOptionPane.showMessageDialog(this, "No questions match these filters.",
                    "No questions", JOptionPane.WARNING_MESSAGE);
            return;
        }
        Collections.shuffle(candidates);
        activeQuiz = new ArrayList<>(candidates.subList(0, Math.min(count, candidates.size())));
        startQuiz();
    }

    private void startQuiz() {
        questionIndex = 0;
        score = 0;
        answered = false;
        cards.show(root, "quiz");
        showQuestion();
    }

    private void showQuestion() {
        if (questionIndex >= activeQuiz.size()) {
            showResults();
            return;
        }
        Question q = activeQuiz.get(questionIndex);
        questionCounter.setText("Question " + (questionIndex + 1) + " of "
                + activeQuiz.size() + "   ·   Score: " + score);
        questionLabel.setText("<html><div style='width:650px'>"
                + html(q.question) + "</div></html>");

        for (int i = 0; i < 4; i++) {
            optionButtons[i].setText("<html><div style='width:620px'>"
                    + (char) ('A' + i) + ". " + html(q.options.get(i)) + "</div></html>");
            optionButtons[i].setEnabled(true);
            optionButtons[i].setSelected(false);
        }
        optionGroup.clearSelection();
        feedbackLabel.setText(" ");
        sourceLabel.setText("Question Bank");
        actionButton.setText("Check answer");
        answered = false;
    }

    private void handleQuizAction() {
        if (questionIndex >= activeQuiz.size()) return;
        Question q = activeQuiz.get(questionIndex);
        if (!answered) {
            int selected = -1;
            for (int i = 0; i < optionButtons.length; i++) {
                if (optionButtons[i].isSelected()) selected = i;
            }
            if (selected < 0) {
                JOptionPane.showMessageDialog(this, "Please select an answer first.",
                        "Choose an option", JOptionPane.INFORMATION_MESSAGE);
                return;
            }
            answered = true;
            for (JRadioButton button : optionButtons) button.setEnabled(false);

            if (selected == q.correctIndex) {
                score++;
                feedbackLabel.setText("<html><b style='color:#16803c'>Correct!</b> "
                        + html(q.explanation) + "</html>");
            } else {
                feedbackLabel.setText("<html><b style='color:#b42318'>Not quite.</b> Correct answer: "
                        + html(q.options.get(q.correctIndex)) + "<br>"
                        + html(q.explanation) + "</html>");
            }
            questionCounter.setText("Question " + (questionIndex + 1) + " of "
                    + activeQuiz.size() + "   ·   Score: " + score);
            actionButton.setText(questionIndex == activeQuiz.size() - 1
                    ? "View results" : "Next question");
        } else {
            questionIndex++;
            showQuestion();
        }
    }

    private void showResults() {
        double percentage = activeQuiz.isEmpty() ? 0 : score * 100.0 / activeQuiz.size();
        String message = String.format(Locale.ROOT,
                "Quiz complete!%n%nScore: %d / %d%nPercentage: %.1f%%%n%nChoose another subject to play again.",
                score, activeQuiz.size(), percentage);
        JOptionPane.showMessageDialog(this, message, "Quiz results",
                JOptionPane.INFORMATION_MESSAGE);
        statusLabel.setText(String.format(Locale.ROOT,
                "Last result: %d/%d (%.1f%%) · %d questions available",
                score, activeQuiz.size(), percentage, localBank.size()));
        cards.show(root, "dashboard");
    }

    private String html(String value) {
        if (value == null) return "";
        return value.replace("&", "&amp;").replace("<", "&lt;")
                .replace(">", "&gt;").replace("\"", "&quot;")
                .replace("'", "&#39;");
    }

