                UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());
                UIManager.put("Panel.background", new Color(245, 248, 252));
                UIManager.put("OptionPane.background", Color.WHITE);
                UIManager.put("OptionPane.messageForeground", new Color(31, 41, 55));
                UIManager.put("Button.background", new Color(239, 244, 250));
                UIManager.put("Button.foreground", new Color(31, 41, 55));
                UIManager.put("ComboBox.background", Color.WHITE);
                UIManager.put("ComboBox.foreground", new Color(31, 41, 55));
